import{_ as a,o as t,c as s,a1 as i}from"./chunks/framework.DaSVVvC-.js";const u=JSON.parse('{"title":"Accessibility","description":"","frontmatter":{},"headers":[],"relativePath":"accessibility.md","filePath":"accessibility.md"}'),o={name:"accessibility.md"};function n(r,e,c,l,d,p){return t(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="accessibility" tabindex="-1">Accessibility <a class="header-anchor" href="#accessibility" aria-label="Permalink to &quot;Accessibility&quot;">​</a></h1><p>Accessibility is treated as a component quality requirement, not a cleanup task.</p><h2 id="baseline-rules" tabindex="-1">Baseline Rules <a class="header-anchor" href="#baseline-rules" aria-label="Permalink to &quot;Baseline Rules&quot;">​</a></h2><ul><li>Use native controls where they exist.</li><li>Use links for navigation and buttons for actions.</li><li>Keep visible focus states.</li><li>Do not remove labels from form controls.</li><li>Use ARIA to clarify behavior, not to recreate native semantics badly.</li><li>Respect reduced-motion preferences.</li><li>Keep token color pairs above contrast requirements.</li></ul><h2 id="component-patterns" tabindex="-1">Component Patterns <a class="header-anchor" href="#component-patterns" aria-label="Permalink to &quot;Component Patterns&quot;">​</a></h2><p><code>my-button</code> renders a real <code>&lt;button&gt;</code> unless <code>href</code> is provided. Link-buttons use an anchor only when the action navigates.</p><p><code>my-input</code> always renders a visible label and connects hint/error text with <code>aria-describedby</code>.</p><p><code>my-disclosure</code> synchronizes <code>open</code>, <code>hidden</code>, and <code>aria-expanded</code>.</p><p><code>my-alert</code> uses <code>role=&quot;status&quot;</code> for non-destructive messages and <code>role=&quot;alert&quot;</code> for danger messages.</p><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span></span></code></pre></div><p>The current checks verify token contrast and manifest completeness. Browser-level keyboard and screen-reader checks should be added as the component set grows.</p>',13)])])}const b=a(o,[["render",n]]);export{u as __pageData,b as default};
